// Decide which scrape (J+7 ou J+14) chaque post necessite, et emit un item
// par scrape a executer. Aucune variable d'environnement, aucun fetch.
const now = new Date();
const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
const FOURTEEN_DAYS = 14 * 24 * 60 * 60 * 1000;
const items = $input.all();
// Le HTTP node retourne {data: [...]} OU directement [...] selon config.
const rows = items.length === 1 && Array.isArray(items[0].json) ? items[0].json : items.map(i => i.json);
const out = [];
for (const r of rows) {
  if (!r || !r.post_id || !r.published_at) continue;
  const pubAt = new Date(r.published_at).getTime();
  const age = now.getTime() - pubAt;
  if (!r.scrape_d7_done && age >= SEVEN_DAYS) {
    out.push({ json: { post_id: r.post_id, days_since_publish: 7, linkedin_url: r.linkedin_url } });
  } else if (!r.scrape_d14_done && age >= FOURTEEN_DAYS) {
    out.push({ json: { post_id: r.post_id, days_since_publish: 14, linkedin_url: r.linkedin_url } });
  }
}
return out;

